	"gift_premium_subtitle": "Anna %1$s vuodeksi lahjaksi käyttäjälle %2$s hintaan %3$s. Kun olet suorittanut maksun, vastaanottaja saa ilmoituksen lähettämästäsi lahjasta.",
	"gift_premium_terms_footer": "Lahjatilauksen hinta veloitetaan ostohetkellä. Maksua ei palauteta. Lahja on kertakäyttöinen, ei vaihdettavissa eikä yhdistettävissä, eikä sillä ole käteisarvoa. Lahjajakso käynnistyy, kun X on tarkistanut saajan tilin; vastaanottajan on hyväksyttävä %1$s ja käytäntömme. Jos vastaanottaja ei täytä kelpoisuusvaatimuksia, peruu tilauksen tai kieltäytyy hyväksymästä ehtoja tai käytäntöjämme, lahjaa ei voi palauttaa eikä maksua palauteta. Osto saattaa aiheuttaa veroseuraamuksia. Ehtoihin voi tulla muutoksia. %2$s.",
