	"go_to_twitter": "Siirry sivustolle x.com",
	"golive__tip_broadcaster_1": "<b>VINKKI:</b> Kiitos, että lähetät suoraa lähetystä! Toivota ihmiset tervetulleiksi heidän alkaessaan seurata lähetystäsi.",
	"golive__tip_broadcaster_10": "<b>VINKKI:</b> Kiitos, että lähetät suoraa lähetystä X:ssä! ≺3",
	"golive__tip_broadcaster_2": "<b>VINKKI:</b> Kokeile tervehtiä ihmisiä nimeltä, kun he alkavat seurata lähetystä – he ilahtuvat!",
	"golive__tip_broadcaster_3": "<b>VINKKI:</b> Ole live-tilassa ainakin muutaman minuutin ajan, jotta ihmiset ehtivät löytää sinut.",
	"golive__tip_broadcaster_4": "<b>VINKKI:</b> Murra jää kysymällä katsojilta, mistä päin he lähetystä katselevat.",
	"golive__tip_broadcaster_5": "<b>VINKKI:</b> Kiitä katsojia ja vastaa heidän kommentteihinsa, jotta mielenkiinto ei lopahda.",
	"golive__tip_broadcaster_6": "<b>VINKKI:</b> Jos yhteytesi katkeaa kesken lähetyksen, siirry paikkaan, jossa verkkoyhteys on parempi.",
	"golive__tip_broadcaster_7": "<b>VINKKI:</b> Pyydä ihmisiä seuraamaan sinua, jotta he saavat ilmoituksen seuraavasta lähetyksestäsi.",
	"golive__tip_broadcaster_8": "<b>VINKKI:</b> Aloita suora lähetys tervehtimällä yleisöä. Uusintakatsojille tulee siitä hyvä mieli.",
	"golive__tip_broadcaster_9": "<b>VINKKI:</b> Kiitä katsojia katselusta, ennen kuin lopetat lähetyksen.",
	"golive__tip_pre_broadcast_1": "<b>VINKKI:</b> Kirjoita otsikko, ennen kuin aloitat suoran lähetyksen, jotta yleisö löytää videosi.",
	"golive__tip_pre_broadcast_2": "<b>VINKKI:</b> Kuvaileva otsikko antaa ihmisille käsityksen lähetyksesi aiheesta.",
	"golive__tip_pre_broadcast_3": "<b>VINKKI:</b> Kaipaatko ideoita? Tarjoa yleisölle kierros, esittele taitojasi tai puhu itseäsi kiinnostavasta aiheesta.",
	"golive__tip_pre_broadcast_4": "<b>VINKKI:</b> Tarkista verkkoyhteytesi vahvuus, ennen kuin aloitat suoran lähetyksen.",
	"golive__tip_pre_broadcast_5": "<b>VINKKI:</b> Lisää otsikkoon avainsana, jotta ihmiset löytävät suoran lähetyksesi.",
	"golive__tip_pre_broadcast_6": "<b>VINKKI:</b> Siinä kaikki vinkit tällä erää – kiitos, että lähetät suorana X:ssä!",
