	"ps__tip_broadcaster_1": "<b>VINKKI:</b> Kiitos lähetyksestä! Muista tervehtiä katsojia heidän liittyessään yleisöön.",
	"ps__tip_broadcaster_11": "<b>VINKKI:</b> Kiitos, että käytät Periscopea lähetykseesi! ≺3",
	"ps__tip_broadcaster_2": "<b>VINKKI:</b> Kokeile uusien katsojien mainitsemista nimeltä. Se ilahduttaa heitä!",
	"ps__tip_broadcaster_3": "<b>VINKKI:</b> Tee lähetyksestä ainakin muutaman minuutin mittainen, jotta ihmiset ehtivät löytää sinut.",
	"ps__tip_broadcaster_4": "<b>VINKKI:</b> Voit rikkoa jään kysymällä katsojilta heidän asuinpaikkaansa.",
	"ps__tip_broadcaster_5": "<b>VINKKI:</b> Kiitä yleisöä lähetyksen katselusta ja vastaa kommentteihin, jotta mielenkiinto ei lopahda.",
	"ps__tip_broadcaster_6": "<b>VINKKI:</b> Jos yhteytesi katkeaa kesken lähetyksen, siirry paikkaan, jossa verkkoyhteys on parempi.",
	"ps__tip_broadcaster_7": "<b>VINKKI:</b> Pyydä katsojia seuraamaan sinua, jotta he saavat ilmoituksen siirtyessäsi live-tilaan.",
	"ps__tip_broadcaster_8": "<b>VINKKI:</b> Aloita lähetys tervehtimällä heti katsojia. Uusintana lähetystä katsoville tulee hyvä mieli.",
	"ps__tip_broadcaster_9": "<b>VINKKI:</b> Kiitä katsojiasi katselusta ennen lähetyksen päättämistä.",
	"ps__tip_pre_broadcast_1": "<b>VINKKI:</b> Anna lähetykselle otsikko ennen aloitusta, jotta tavoitat ihmisiä, joita kiinnostavat samat asiat kuin itseäsi!",
	"ps__tip_pre_broadcast_2": "<b>VINKKI:</b> Kuvaileva otsikko kertoo ihmisille, mitä lähetyksesi käsittelee.",
	"ps__tip_pre_broadcast_3": "<b>VINKKI:</b> Kaipaatko ideoita? Vie katsojat kierrokselle, esittele osaamistasi tai puhu itseäsi kiinnostavasta aiheesta.",
	"ps__tip_pre_broadcast_4": "<b>VINKKI:</b> Varmista ennen lähetyksen aloitusta, että verkkoyhteys on hyvä.",
	"ps__tip_pre_broadcast_5": "<b>VINKKI:</b> Jakamalla lähetyksesi X:ssä saat enemmän katsojia.",
	"ps__tip_pre_broadcast_6": "<b>VINKKI:</b> Jos seuraat käyttäjiä, jotka vastavuoroisesti seuraavat sinua, voit lähettää heille yksityislähetyksiä.",
	"ps__tip_pre_broadcast_8": "<b>VINKKI:</b> Käytä otsikossa avainsanaa, joka auttaa ihmisiä löytämään lähetyksesi.",
	"ps__tip_pre_broadcast_9": "<b>VINKKI:</b> Siinä kaikki vinkit tällä erää - kiitos, että käytät Periscopea!",
	"ps__tip_viewer_1": "<b>VINKKI:</b> Olet ensimmäisten katsojien joukossa. Kirjoita tervehdyksesi kommenttikenttään!",
	"ps__tip_viewer_2": "<b>VINKKI:</b> Kirjoita kommentti, niin että <b>%1$s</b> tietää sinun olevan katsomossa!",
	"ps__tip_viewer_3": "<b>VINKKI:</b> Kerro lähettäjälle <b>%1$s</b>, missä katselet lähetystä!",
	"ps__tip_viewer_4": "<b>VINKKI:</b>Kirjoita tervehdyksesi. Voit jutella lähettäjän <b>%1$s</b> ja muiden katsojien kanssa.",
	"ps__toast_broadcast_notify_followers": "Olemme ilmoittaneet seuraajillesi, että liityit mukaan vieraana",
