	"tipjar_input_rationale_kakao_pay": "\"Käyttäjät lähettävät tipit yllä ilmoittamallesi QR-linkille.\nLisäämällä oman QR-linkkisi ja hyväksymällä tipit saatat paljastaa itsestäsi tietoja, joita olet antanut maksupalveluyritykselle, kuten nimesi ja sähköpostiosoitteesi.\n\nKakao Payn QR-linkki löytyy kohdasta KakaoTalk More > Scanner oikeassa yläkulmassa > Money Code > Leikepöytä-kuvake. Kopioi linkki leikepöydällesi kuvaketta napauttamalla ja liimaa se sitten tähän yläpuolelle.\"",
